/**
 * Custom Tools API module
 * Handles custom tool operations: list, create, read, update, delete, execute
 */

export const customToolsModule = (API) => ({
  async list() {
    return API.get('/api/projects/custom-tools')
  },

  async get(toolId) {
    return API.get(`/api/projects/custom-tools/${toolId}`)
  },

  async create(tool) {
    return API.post('/api/projects/custom-tools', tool)
  },

  async update(toolId, tool) {
    return API.put(`/api/projects/custom-tools/${toolId}`, tool)
  },

  async delete(toolId) {
    return API.delete(`/api/projects/custom-tools/${toolId}`)
  },

  async execute(toolId, parameters) {
    return API.post(`/api/projects/custom-tools/${toolId}/execute`, {
      parameters
    })
  },

  async executeBackground(toolId, parameters) {
    // Execute tool via socket for long-running operations
    if (!API.socket) {
      throw new Error('Socket not connected')
    }
    return new Promise((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        reject(new Error('Tool execution timed out'))
      }, 300000)

      API.socket.emit('codx-junior-execute-tool', {
        tool_id: toolId,
        parameters: parameters
      }, (response) => {
        clearTimeout(timeoutId)
        if (response?.error) {
          reject(new Error(response.error))
        } else {
          resolve(response)
        }
      })
    })
  }
})

