/**
 * Create a new empty CustomTool with defaults
 */
export function createEmptyCustomTool(overrides?: Partial<CustomTool>): CustomTool {
  return {
    id: '',
    name: '',
    description: '',
    language: 'sh',
    script_body: '',
    parameters: [],
    active: true,
    ...overrides
  }
}

/**
 * Validate CustomTool ID (must be valid Python identifier)
 */
export function isValidToolId(id: string): boolean {
  if (!id || id.length === 0) return false
  const pythonIdentifierRegex = /^[a-zA-Z_][a-zA-Z0-9_]*$/
  return pythonIdentifierRegex.test(id)
}

/**
 * Validate CustomToolParameter
 */
export function isValidParameter(param: CustomToolParameter): string | null {
  if (!param.name || param.name.length === 0) {
    return 'Parameter name is required'
  }
  if (!isValidToolId(param.name)) {
    return `Parameter name "${param.name}" must be a valid Python identifier`
  }
  if (!param.param_type || param.param_type.length === 0) {
    return 'Parameter type is required'
  }
  const validTypes = [
    'str', 'string', 'int', 'float', 'bool',
    'list', 'dict', 'List[str]', 'List[int]',
    'List[Any]', 'Dict[str, Any]', 'Optional[str]'
  ]
  if (!validTypes.includes(param.param_type)) {
    return `Parameter type "${param.param_type}" is not supported`
  }
  return null
}

