 * Validate CustomTool
 */
export function validateCustomTool(tool: CustomTool): string | null {
  if (!tool.id || tool.id.length === 0) {
    return 'Tool ID is required'
  }
  if (!isValidToolId(tool.id)) {
    return `Tool ID "${tool.id}" must be a valid Python identifier`
  }
  if (!tool.name || tool.name.length === 0) {
    return 'Tool name is required'
  }
  if (!tool.script_body || tool.script_body.length === 0) {
    return 'Script body is required'
  }
  if (tool.language && !['sh', 'bash'].includes(tool.language)) {
    return 'Language must be "sh" or "bash"'
  }
  if (tool.parameters && tool.parameters.length > 0) {
    for (const param of tool.parameters) {
      const error = isValidParameter(param)
      if (error) return error
    }
  }
  return null
}

