import { type CustomToolParameter } from '@/types/customTool'

// Supported parameter types
export const SUPPORTED_PARAM_TYPES = {
  str: String,
  int: Number,
  float: Number,
  bool: Boolean,
  list: Array,
  dict: Object,
  'List[str]': Array,
  'List[int]': Array,
  'List[Any]': Array,
  'Dict[str, Any]': Object,
  'Optional[str]': String
}

/**
 * Validates tool ID is a valid Python identifier
 */
export function isValidToolId(id) {
  if (!id) return false
  return /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(id)
}

/**
 * Validates parameter name is a valid Python identifier
 */
export function isValidParamName(name) {
  if (!name) return false
  return /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name)
}

/**
 * Validates a single parameter
 */
export function isValidParameter(param) {
  if (!param.name) return 'Name required'
  if (!isValidParamName(param.name)) return 'Invalid Python identifier'
  if (!param.param_type) return 'Type required'
  if (!Object.keys(SUPPORTED_PARAM_TYPES).includes(param.param_type)) return 'Unsupported type'
  return null
}

/**
 * Validates entire custom tool
 */
export function validateCustomTool(tool) {
  if (!tool.name?.trim()) return 'Tool name is required'
  if (!tool.script_body?.trim()) return 'Script content is required'
  if (tool.parameters?.some(p => isValidParameter(p))) {
    const invalidParam = tool.parameters.find(p => isValidParameter(p))
    return `Parameter error: ${isValidParameter(invalidParam)}`
  }
  return null
}

/**
 * Creates empty tool object for form initialization (ID not set for creation)
 */
export function createEmptyCustomTool() {
  return {
    id: '', // Will be generated by backend on creation
    name: '',
    description: '',
    script_body: '',
    language: 'sh',
    parameters: [],
    active: true,
    created_by: '',
    created_at: null,
    updated_at: null,
    project_id: ''
  }
}

/**
 * Prepares tool data for creation (removes ID if empty)
 */
export function prepareToolForCreation(tool) {
  const { id, ...rest } = tool
  return rest // Don't send ID to backend for creation
}

/**
 * Prepares tool data for update
 */
export function prepareToolForUpdate(tool) {
  return tool
}

