  if (!tool.name || tool.name.trim() === '') {
    return 'Tool name is required'
  }
  if (!tool.script_body || tool.script_body.trim() === '') {
    return 'Script body is required'
  }
  if (tool.parameters && tool.parameters.length > 0) {
    for (let i = 0; i < tool.parameters.length; i++) {
      const error = isValidParameter(tool.parameters[i])
      if (error) return error
    }
  }
  return null
}

/**
 * Validate a single parameter
 * @returns {string|null} Error message or null if valid
 */
export function isValidParameter(param) {
  if (!param.name || param.name.trim() === '') {
    return 'Parameter name is required'
  }
  if (!param.description || param.description.trim() === '') {
    return 'Parameter description is required'
  }
  if (!param.param_type) {
    return 'Parameter type is required'
  }
  return null
}

/**
 * Check if tool ID is valid
 */
export function isValidToolId(id) {
  return id && id.trim() !== '' && /^[a-zA-Z0-9_-]+$/.test(id)
}

